import { useState } from "react";
import axios from "axios";
import api from "../../api";
import { TOUCHPOINT_LABEL } from "../../constants/touchpoints";
import { SectionCard } from "../ui/SectionCard";

/** What GET /api/leads/:id/snapshot returns (generated by pitchr-ai). */
interface LeadSnapshotData {
  lastContact: { date: string; daysAgo: number; type: string } | null;
  lastActivity: { date: string; daysAgo: number; description: string } | null;
  effort: Record<string, number>;
  analysis: {
    headline: string;
    decisionMaker: string;
    keyFacts: string[];
    odds: "high" | "medium" | "low" | "unknown";
    oddsReason: string;
    goal: string;
    suggestedApproach: string;
  };
}

const ODDS_STYLES: Record<LeadSnapshotData["analysis"]["odds"], string> = {
  high: "bg-green-50 text-green-700 border-green-200",
  medium: "bg-amber-50 text-amber-700 border-amber-200",
  low: "bg-slate-100 text-slate-600 border-slate-200",
  unknown: "bg-gray-50 text-gray-500 border-gray-200",
};

const EFFORT_LABELS: Record<string, [singular: string, plural: string]> = {
  visits: ["visit", "visits"],
  emails: ["email", "emails"],
  calls: ["call", "calls"],
  dms: ["DM", "DMs"],
  texts: ["text", "texts"],
  meetings: ["meeting", "meetings"],
  networkingEvents: ["networking event", "networking events"],
  walkUps: ["walk-up", "walk-ups"],
  referralOutreach: ["referral", "referrals"],
  other: ["other", "other"],
};

// "2026-05-06" -> "5/6/26". Parsed by hand: new Date("2026-05-06") is UTC
// midnight, which shows as the previous day in US time zones.
const formatDate = (isoDate: string) => {
  const [year, month, day] = isoDate.split("-");
  return `${Number(month)}/${Number(day)}/${year.slice(2)}`;
};

const daysAgoLabel = (days: number) =>
  days <= 0 ? "today" : days === 1 ? "yesterday" : `${days} days ago`;

export const LeadSnapshot = ({ leadId }: { leadId: string }) => {
  const [snapshot, setSnapshot] = useState<LeadSnapshotData | null>(null);
  const [generatedAt, setGeneratedAt] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const generate = async () => {
    setLoading(true);
    setError("");
    try {
      const res = await api.get<LeadSnapshotData>(`/api/leads/${leadId}/snapshot`);
      setSnapshot(res.data);
      setGeneratedAt(new Date());
    } catch (err) {
      // NestJS sends a readable message (e.g. "The snapshot service is unavailable")
      const message = axios.isAxiosError(err) ? err.response?.data?.message : null;
      setError(message ?? "Couldn't generate the snapshot. Try again.");
    } finally {
      setLoading(false);
    }
  };

  // ── Not generated yet ──────────────────────────────────────────────────
  if (!snapshot && !loading && !error) {
    return (
      <SectionCard className="rounded-xl p-4 mb-6 flex items-center justify-between gap-4">
        <div className="min-w-0">
          <p className="text-sm font-semibold text-gray-700">✨ Lead snapshot</p>
          <p className="text-xs text-gray-400 mt-0.5">
            AI summary of where this lead stands and how to approach them
          </p>
        </div>
        <button
          onClick={generate}
          className="flex-shrink-0 text-sm bg-green-primary text-white px-3 py-1.5 rounded-lg"
        >
          Generate
        </button>
      </SectionCard>
    );
  }

  return (
    <SectionCard className="rounded-xl p-4 md:p-5 mb-6">
      {/* Header */}
      <div className="flex items-center justify-between gap-3 mb-3">
        <div className="flex items-center gap-2">
          <p className="text-sm font-semibold text-gray-700">✨ Lead snapshot</p>
          {snapshot && !loading && (
            <span
              className={`text-xs font-medium border px-2 py-0.5 rounded-full ${
                ODDS_STYLES[snapshot.analysis.odds]
              }`}
            >
              {snapshot.analysis.odds} odds
            </span>
          )}
        </div>
        {!loading && (
          <button
            onClick={generate}
            className="text-xs text-gray-500 hover:text-gray-800 transition"
          >
            {error ? "Try again" : "↻ Refresh"}
          </button>
        )}
      </div>

      {/* Loading */}
      {loading && (
        <div className="space-y-2.5 py-1" aria-live="polite">
          <p className="text-xs text-gray-400">Reading this lead's history…</p>
          <div className="h-4 bg-gray-100 rounded animate-pulse w-3/4" />
          <div className="h-3 bg-gray-100 rounded animate-pulse w-full" />
          <div className="h-3 bg-gray-100 rounded animate-pulse w-5/6" />
          <div className="h-3 bg-gray-100 rounded animate-pulse w-2/3" />
        </div>
      )}

      {/* Error */}
      {error && !loading && <p className="text-sm text-red-500">{error}</p>}

      {/* Snapshot */}
      {snapshot && !loading && !error && (
        <div className="text-sm">
          <p className="text-base font-semibold text-gray-900 leading-snug">
            {snapshot.analysis.headline}
          </p>

          {/* Computed facts */}
          <div className="mt-3 space-y-1 text-xs text-gray-500">
            <p>
              <span className="font-medium text-gray-600">Last contact:</span>{" "}
              {snapshot.lastContact
                ? `${formatDate(snapshot.lastContact.date)} · ${
                    TOUCHPOINT_LABEL[snapshot.lastContact.type] ??
                    snapshot.lastContact.type
                  } · ${daysAgoLabel(snapshot.lastContact.daysAgo)}`
                : "never"}
            </p>
            <p>
              <span className="font-medium text-gray-600">Last activity:</span>{" "}
              {snapshot.lastActivity
                ? `${formatDate(snapshot.lastActivity.date)} · ${
                    snapshot.lastActivity.description
                  } · ${daysAgoLabel(snapshot.lastActivity.daysAgo)}`
                : "none from them yet"}
            </p>
          </div>
          <div className="flex flex-wrap gap-1.5 mt-2">
            {Object.entries(snapshot.effort)
              .filter(([, count]) => count > 0)
              .map(([key, count]) => {
                const [singular, plural] = EFFORT_LABELS[key] ?? [key, key];
                return (
                  <span
                    key={key}
                    className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full"
                  >
                    {count} {count === 1 ? singular : plural}
                  </span>
                );
              })}
          </div>

          {/* Judgment */}
          <p className="mt-4 text-gray-700">
            <span className="font-medium text-gray-900">Decision-maker:</span>{" "}
            {snapshot.analysis.decisionMaker}
          </p>
          <ul className="mt-2 space-y-1.5 list-disc pl-5 text-gray-700">
            {snapshot.analysis.keyFacts.map((fact) => (
              <li key={fact}>{fact}</li>
            ))}
          </ul>

          {/* Next move */}
          <div className="mt-4 rounded-lg border-l-4 border-green-primary bg-green-50/60 px-3 py-2.5 space-y-1.5">
            <p className="text-gray-800">
              <span className="font-semibold">Goal:</span> {snapshot.analysis.goal}
            </p>
            <p className="text-gray-800">
              <span className="font-semibold">Approach:</span>{" "}
              {snapshot.analysis.suggestedApproach}
            </p>
          </div>

          <p className="mt-3 text-xs text-gray-400">
            Why {snapshot.analysis.odds}: {snapshot.analysis.oddsReason}
          </p>
          {generatedAt && (
            <p className="mt-1 text-xs text-gray-300">
              Generated{" "}
              {generatedAt.toLocaleTimeString([], {
                hour: "numeric",
                minute: "2-digit",
              })}
            </p>
          )}
        </div>
      )}
    </SectionCard>
  );
};
